const body = msg.payload;
if (!body || typeof body !== "object" || Array.isArray(body)) {
    msg.statusCode = 400;
    msg.payload = { error: "sensor status must be a JSON object" };
    return msg;
}
for (const key of ["camera_online", "lidar_online"]) {
