        msg.statusCode = 400;
        msg.payload = { error: key + " must be a boolean" };
        return msg;
    }
}
if (body.camera_stream_url !== undefined) {
    if (typeof body.camera_stream_url !== "string") {
        msg.statusCode = 400;
        msg.payload = { error: "camera_stream_url must be a string" };
        return msg;
    }
    if (body.camera_stream_url !== "") {
        let parsed;
        try { parsed = new URL(body.camera_stream_url); } catch (error) {
            msg.statusCode = 400;
            msg.payload = { error: "camera_stream_url must be a valid HTTP or HTTPS URL" };
            return msg;
        }
        if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
            msg.statusCode = 400;
            msg.payload = { error: "camera_stream_url must use HTTP or HTTPS" };
            return msg;
        }
    }
